def current_language() -> str:
    from state import S
    lang = S.ui.get("language", "English")
    return lang if lang in LANGUAGES else "English"


def tr(text: str, **kwargs) -> str:
    translated = LANGUAGES.get(current_language(), {}).get(text, text)
    return translated.format(**kwargs) if kwargs else translated


_language_listeners: list = []
_language_listeners_lock = _threading.Lock()


def register_language_listener(fn) -> None:
    with _language_listeners_lock:
        if fn not in _language_listeners:
            _language_listeners.append(fn)


def unregister_language_listener(fn) -> None:
    with _language_listeners_lock:
        try:
            _language_listeners.remove(fn)
        except ValueError:
            pass


def notify_language_listeners() -> None:
    with _language_listeners_lock:
        listeners = list(_language_listeners)
    for fn in listeners:
        try:
            fn()
        except ValueError:
            pass
